package com.digitalbase.ticketing.service;import com.digitalbase.ticketing.dto.NotificationDto;import com.digitalbase.ticketing.exception.ResourceNotFoundException; // 👈 အသစ် Import လုပ်ထားပါသည်import com.digitalbase.ticketing.model.Notification;import com.digitalbase.ticketing.model.User;import com.digitalbase.ticketing.repository.NotificationRepository;import com.digitalbase.ticketing.repository.UserRepository;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.data.domain.PageRequest;import org.springframework.data.domain.Pageable;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;import java.io.IOException;import java.util.List;import java.util.Map;import java.util.concurrent.ConcurrentHashMap;import java.util.concurrent.CopyOnWriteArrayList;import java.util.stream.Collectors;@Service@RequiredArgsConstructorpublic class NotificationSseServiceImpl implements NotificationSseService {    // Ticket ID အစား User ၏ Email ဖြင့် Connection များကို မှတ်သားပါမည်    private final Map<String, List<SseEmitter>> userEmittersMap = new ConcurrentHashMap<>();    private final NotificationRepository notificationRepository;    private final UserRepository userRepository;    @Override    public SseEmitter subscribe(String email) {        SseEmitter emitter = new SseEmitter(3600000L); // 1 Hour        userEmittersMap.computeIfAbsent(email, k -> new CopyOnWriteArrayList<>()).add(emitter);        emitter.onCompletion(() -> removeEmitter(email, emitter));        emitter.onTimeout(() -> removeEmitter(email, emitter));        emitter.onError((e) -> removeEmitter(email, emitter));        return emitter;    }    private void removeEmitter(String email, SseEmitter emitter) {        List<SseEmitter> emitters = userEmittersMap.get(email);        if (emitters != null) {            emitters.remove(emitter);            if (emitters.isEmpty()) {                userEmittersMap.remove(email);            }        }    }    @Override    @Transactional    public void sendNotification(String userEmail, Notification notificationEntity) {        // ၁။ DB သို့ အရင် သိမ်းပါမည်        Notification savedNotification = notificationRepository.save(notificationEntity);        // ၂။ Frontend အတွက် DTO ပြောင်းပါမည်        NotificationDto dto = mapToDto(savedNotification);        // ၃။ ထို User လိုင်းပေါ်ရှိနေပါက Live လွှင့်ပါမည် (Real-time Push)        List<SseEmitter> emitters = userEmittersMap.get(userEmail);        if (emitters != null && !emitters.isEmpty()) {            for (SseEmitter emitter : emitters) {                try {                    emitter.send(SseEmitter.event().name("new-notification").data(dto));                } catch (IOException e) {                    emitter.complete();                    removeEmitter(userEmail, emitter);                }            }        }    }    @Override    public Page<NotificationDto> getUserNotifications(String email, int page, int size) {        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        // 👇 Pageable တည်ဆောက်ခြင်း (Repository Method တွင် OrderBy ပါပြီးသားဖြစ်၍ Sort ထပ်မလိုပါ)        Pageable pageable = PageRequest.of(page, size);        // 👇 List အစား Page ဖြင့် ပြောင်းလဲလက်ခံခြင်း        Page<Notification> notifications = notificationRepository.findByUserIdOrderByCreatedAtDesc(user.getId(), pageable);        // 👇 stream() မလိုဘဲ Page ၏ map() ကို တိုက်ရိုက်ခေါ်သုံးနိုင်ပါသည်        return notifications.map(this::mapToDto);    }    @Override    @Transactional    public void markAllAsRead(String email) {        // 🎯 orElseThrow တွင် ResourceNotFoundException ကို တိကျစွာ ထည့်ထားပါသည်        User user = userRepository.findByEmail(email)                .orElseThrow(() -> new ResourceNotFoundException("User not found"));        List<Notification> unreadNotis = notificationRepository.findByUserIdAndIsReadFalse(user.getId());        for (Notification noti : unreadNotis) {            noti.setRead(true);        }        notificationRepository.saveAll(unreadNotis);    }    private NotificationDto mapToDto(Notification noti) {        return NotificationDto.builder()                .id(noti.getId())                .type(noti.getType().name())                .title(noti.getTitle())                .message(noti.getMessage())                .actionText(noti.getActionText())                .actionUrl(noti.getActionUrl())                .isRead(noti.isRead())                .createdAt(noti.getCreatedAt())                .build();    }}